package com.ataglanceplus.cards

import androidx.annotation.DrawableRes
import com.ataglanceplus.R
import com.ataglanceplus.complications.ChipValues

/**
 * A chip's Material You tonal palette (chips spec 2.2): its background as a pill and as a stacked
 * card (generated by tools/gen_chip_tones.py), and the colours of its icon, its value and its
 * second lines.
 */
data class ChipTone(@DrawableRes val pill: Int, @DrawableRes val stack: Int, val icon: Int, val text: Int, val secondary: Int)

object ChipTones {

    private const val WHITE = 0xFFFFFFFF.toInt()
    private const val GREY = 0xFFC4C6D0.toInt()

    private fun tone(pill: Int, stack: Int, icon: Long, text: Long = 0xFFFFFFFF, secondary: Long = 0xFFC4C6D0) =
        ChipTone(pill, stack, icon.toInt(), text.toInt(), secondary.toInt())

    private val GMAIL = tone(R.drawable.chip_tone_gmail, R.drawable.chip_tone_gmail_stack, 0xFFD3E3FD)
    private val CALLS = tone(R.drawable.chip_tone_calls, R.drawable.chip_tone_calls_stack, 0xFFFF897D, 0xFFFFDAD6)
    private val TEXTS = tone(R.drawable.chip_tone_texts, R.drawable.chip_tone_texts_stack, 0xFF80CBC4, 0xFFE0F7FA)
    private val NOTIF = tone(R.drawable.chip_tone_notif, R.drawable.chip_tone_notif_stack, 0xFFEADDFF)
    private val STEPS = tone(R.drawable.chip_tone_steps, R.drawable.chip_tone_steps_stack, 0xFF6DD58C, secondary = 0xFFB7E1CD)
    private val SLEEP = tone(R.drawable.chip_tone_sleep, R.drawable.chip_tone_sleep_stack, 0xFF8AB4F8)
    private val HEALTH = tone(R.drawable.chip_tone_health, R.drawable.chip_tone_health_stack, 0xFFFF8A80, secondary = 0xFFF2B8B5)
    private val BATTERY = tone(R.drawable.chip_tone_battery, R.drawable.chip_tone_battery_stack, 0xFF81C995)
    private val BUDS = tone(R.drawable.chip_tone_buds, R.drawable.chip_tone_buds_stack, 0xFF78D9EC, secondary = 0xFFB2EBF2)
    private val SCREEN = tone(R.drawable.chip_tone_screen, R.drawable.chip_tone_screen_stack, 0xFFA8C7FA)
    private val ALARM = tone(R.drawable.chip_tone_alarm, R.drawable.chip_tone_alarm_stack, 0xFFFDD663)
    private val COUNT = tone(R.drawable.chip_tone_count, R.drawable.chip_tone_count_stack, 0xFFA8C7FA)
    private val SUNSET = tone(R.drawable.chip_tone_sunset, R.drawable.chip_tone_sunset_stack, 0xFFFFB74D, secondary = 0xFFFFE0B2)
    private val ETORO = tone(R.drawable.chip_tone_etoro, R.drawable.chip_tone_etoro_stack, 0xFF6DD58C, secondary = 0xFF6DD58C)
    private val ETORO_DOWN = tone(R.drawable.chip_tone_etoro_loss, R.drawable.chip_tone_etoro_loss_stack, 0xFFFF8A80, secondary = 0xFFFF8A80)
    private val TICKET = tone(R.drawable.chip_tone_ticket, R.drawable.chip_tone_ticket_stack, 0xFFD0BCFF)

    fun of(spec: ChipSpec, value: ChipValues.Value): ChipTone = when (spec.kind) {
        Complication.GMAIL -> GMAIL
        Complication.MISSED_CALLS -> CALLS
        Complication.TEXTS -> TEXTS
        Complication.APP_NOTIFICATIONS -> NOTIF
        Complication.STEPS -> STEPS
        Complication.SLEEP -> SLEEP
        Complication.HEALTH -> HEALTH
        Complication.BATTERY -> BATTERY
        Complication.BUDS -> BUDS
        Complication.SCREEN_TIME -> SCREEN
        Complication.ALARM -> ALARM
        Complication.COUNTDOWN -> COUNT
        Complication.SUNSET -> SUNSET
        Complication.ETORO -> if (value.down) ETORO_DOWN else ETORO
        Complication.RAIL_TICKET -> TICKET
    }
}
